"""Actual private rich note conversion, native formatting/paste and process restoration."""
import json,uuid,time
from playwright.sync_api import expect

def verify_rich_notes(page,project,mount,send,envelope,settle,restart):
 page.set_viewport_size({'width':1440,'height':1000});before={p:p.read_bytes() for p in project.iterdir() if p.is_file()};external=[]
