 ready();add('메모 만들기',300,180);original='Legacy <b>literal</b>\nsecond line';plain=page.locator('.workspace-note').last;legacy=plain.get_attribute('data-workspace-item');plain.locator('textarea').fill(original);flush();restart();ready();expect(note(legacy).locator('textarea')).to_have_value(original);expect(note(legacy).locator('[data-note-editor]')).to_have_count(0)
