 # Browser-local clipboard fixture; paste uses the real contenteditable paste event.
 page.context.grant_permissions(['clipboard-read','clipboard-write']);payload='<b>Pasted allowed</b><img src="https://notes-paste.invalid/image" onerror="globalThis.__noteInjected=true"><script>globalThis.__noteInjected=true</script><a href="javascript:alert(1)">Link text</a><span style="background-image:url(https://notes-paste.invalid/css)" onclick="globalThis.__noteInjected=true">Safe text</span>'
 page.evaluate("async html=>navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([html],{type:'text/html'})})])",payload);editor(id).press('Control+End');editor(id).press('Enter');editor(id).press('Control+v');expect(editor(id)).to_contain_text('Pasted allowed');expect(editor(id).locator('img,script,a,iframe,svg,[onclick],[onerror]')).to_have_count(0);assert not editor(id).evaluate("el=>el.innerHTML.includes('url(')");assert not page.evaluate('()=>globalThis.__noteInjected');assert not external,external
 # Color controls are set through their browser input event; no native OS picker is claimed.
 editor(id).press('Control+a');note(id).locator('[data-note-color]').evaluate("el=>{el.value='#efca78';el.dispatchEvent(new Event('input',{bubbles:true}))}");note(id).locator('.workspace-item-handle').click(button='right',position={'x':80,'y':18});page.get_by_role('button',name='제목 서식',exact=True).click();dialog=page.get_by_role('dialog',name='제목 서식',exact=True);dialog.locator('[data-title-size]').fill('22');dialog.locator('[data-title-color]').evaluate("el=>{el.value='#123456';el.dispatchEvent(new Event('input',{bubbles:true}))}");dialog.locator('[data-title-apply]').click();expect(note(id).locator('.workspace-item-name')).to_have_css('font-size','22px');expect(note(id).locator('.workspace-item-name')).to_have_css('color','rgb(18, 52, 86)')
 flush();snapshot=state()['presentation'];item=next(item for item in snapshot['workspaceItems'] if item['id']==id);assert 'Pasted allowed' in item['text'] and 'script>' not in item['richText'] and 'url(' not in item['richText'];assert item['titleStyle']=={'size':22,'color':'#123456'};legacy_item=next(item for item in snapshot['workspaceItems'] if item['id']==legacy);assert legacy_item['text']==original and 'richText' not in legacy_item
 page.screenshot(path='/tmp/confectory-v480-rich-note.png',full_page=True)
 # Notes stay in their own Workspace; the current runtime transfers windows through portals.
