 # Restored private HTML is sanitized on display without rewriting the saved note on read.
 flush();restored=state()['presentation'];target_item=next(item for item in restored['workspaceItems'] if item['id']==id);raw='<b>Restored allowed</b><img src="https://notes-paste.invalid/restore" onerror="globalThis.__noteInjected=true"><script>globalThis.__noteInjected=true</script>';target_item['richText']=raw;old_mirror=target_item['text'];invoke('savePresentation',{'presentation':restored});restart();ready();expect(editor(id)).to_contain_text('Restored allowed');expect(editor(id).locator('img,script,iframe,svg,[onerror]')).to_have_count(0);assert not page.evaluate('()=>globalThis.__noteInjected') and not external;flush();current=state()['presentation'];stored=next(item for item in current['workspaceItems'] if item['id']==id);assert stored['richText']==raw and stored['text']==old_mirror,'display must not migrate saved private source';editor(id).fill('Reviewed clean note');flush();current=state()['presentation'];stored=next(item for item in current['workspaceItems'] if item['id']==id);assert 'Restored allowed' not in stored['richText'] and 'notes-paste.invalid' not in stored['richText'] and '<script' not in stored['richText'] and stored['text']=='Reviewed clean note',stored
 assert all(p.read_bytes()==value for p,value in before.items()),'private note formatting changed source files'
